// Kontrollerar att inga sidor hämtar typsnitt eller annat från Google Fonts, och att de lokala filerna finns.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs'), path = require('path');
function alla(d) { return fs.readdirSync(d, { withFileTypes: true }).flatMap(e => e.isDirectory() ? alla(path.join(d, e.name)) : [path.join(d, e.name)]); }
const sidor = alla('public').filter(f => /\.(html|css|js)$/.test(f));
const google = sidor.filter(f => /fonts\.(googleapis|gstatic)\.com/.test(fs.readFileSync(f, 'utf8')));
const css = fs.readFileSync('public/fonts/typsnitt.css', 'utf8');
const filer = [...css.matchAll(/url\((\/fonts\/[^)]+)\)/g)].map(m => m[1]);
const saknas = filer.filter(f => !fs.existsSync(path.join('public', f)));
const krav = {
  ingenGoogleFonts: google.length === 0,
  lokalaFilerFinns: filer.length >= 7 && saknas.length === 0,
  startsidanLokalt: fs.readFileSync('public/index.html', 'utf8').includes('href="/fonts/typsnitt.css"'),
  vssLokalt: ['public/vreta-sound-system/index.html', 'public/vreta-sound-system/en/index.html'].every(f => fs.readFileSync(f, 'utf8').includes('href="/fonts/typsnitt.css"')),
  allaFamiljer: ['Inter', 'Bodoni Moda', 'DM Mono', 'Instrument Sans'].every(n => css.includes("font-family:'" + n + "'")),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, google, saknas, ok }));
process.exit(ok ? 0 : 1);
